<?php $statusLabels=['open'=>'Offen','waiting_admin'=>'Wartet auf Admin','waiting_seller'=>'Wartet auf Verkäuferin','closed'=>'Geschlossen'];$senderLabels=['seller'=>'Verkäuferin','admin'=>'Admin','guest'=>'Gast','system'=>'System'];?>
<main class="section narrow">
<div class="admin-page-intro"><div><span class="eyebrow"><?=App\Core\View::e($ticket['ticket_number'])?></span><h1><?=App\Core\View::e($ticket['subject'])?></h1><p><?=App\Core\View::e($ticket['name'])?> · <?=App\Core\View::e($ticket['email'])?></p></div><a class="btn ghost" href="/admin/support">Zurück</a></div>
<section class="card admin-form"><div class="section-head compact"><div><h2>Bearbeitungsstatus</h2><p class="muted">Aktuell: <?=App\Core\View::e($statusLabels[$ticket['status']]??$ticket['status'])?></p></div></div><form method="post" action="/admin/support/<?=$ticket['id']?>/status" class="row-actions"><?=App\Core\Csrf::field()?><select name="status"><?php foreach($statusLabels as $k=>$v):?><option value="<?=$k?>" <?=$ticket['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn">Status aktualisieren</button></form></section>
<section class="card chat seller-section-card"><div class="chat-log"><?php foreach($messages as $m):?><div class="message <?=$m['sender_type']==='admin'?'admin':'seller'?>"><small><?=App\Core\View::e($senderLabels[$m['sender_type']]??$m['sender_type'])?> · <?=date('d.m.Y H:i',strtotime($m['created_at']))?></small><p><?=nl2br(App\Core\View::e($m['message']))?></p></div><?php endforeach;?></div><?php if($ticket['status']!=='closed'):?><form method="post" action="/admin/support/<?=$ticket['id']?>/antwort" class="chat-form"><?=App\Core\Csrf::field()?><textarea name="message" rows="4" required placeholder="Antwort an die anfragende Person"></textarea><button class="btn primary">Antwort senden</button></form><?php endif;?></section>
